def resolve_market_knowledge(country_name):
    c = str(country_name).strip()
    if c in ['Egypt', 'EG', 'Mısır']:
        c = 'Egypt'
    elif c in ['Jordan', 'JO', 'Ürdün']:
        c = 'Jordan'
    elif c in ['Iraq', 'IQ', 'Irak']:
        c = 'Iraq'
    elif c in ['Jordan-Iraq', 'Jordan & Iraq', 'Ürdün-Irak']:
        c = 'Jordan-Iraq'
    elif c in ['Qatar', 'QA', 'Katar']:
        c = 'Qatar'
    elif c in ['Saudi Arabia', 'SA', 'KSA', 'Suudi Arabistan']:
        c = 'Saudi Arabia'
    elif c in ['Algeria', 'DZ', 'Cezayir']:
        c = 'Algeria'
    elif c in ['Turkey', 'TR', 'Türkiye']:
        c = 'Turkey'
    elif c in ['Italy', 'IT', 'İtalya']:
        c = 'Italy'
    elif c in ['Germany', 'DE', 'Almanya']:
        c = 'Germany'
    elif c in ['Spain', 'ES', 'İspanya']:
        c = 'Spain'
    elif c in ['United Arab Emirates', 'UAE', 'AE', 'BAE']:
        c = 'United Arab Emirates'
    elif c in ['Kuwait', 'KW', 'Kuveyt']:
        c = 'Kuwait'
    elif c in ['United Kingdom', 'UK', 'GB', 'İngiltere']:
        c = 'United Kingdom'
    elif c in ['Azerbaijan', 'AZ', 'Azerbaycan']:
        c = 'Azerbaijan'
    
    if c in MARKET_KNOWLEDGE_BASE:
        res = dict(MARKET_KNOWLEDGE_BASE[c])
        deep = resolve_deep_country_intelligence(c)
        for k in ['customs_regulatory', 'ivf_pgt_regulatory', 'pricing_forecasts', 'expert_opinions', 'sales_strategy']:
            if k not in res:
                res[k] = deep.get(k, {})
        return res
    
    # Generic fallback
    return {
        'authority_name': 'International Health Authorities & Harmonized Medical Registration Board',
        'specialist_name': 'Global Medical Device Regulatory Board & Clinical Evaluation Committee',
        'expert_stance': 'Standard Evaluation (Margin Protection & Collateral Requirement)',
        'expert_max_discount': 6.0,
        'expert_rec_sarf_disc': 7.5,
        'clinical_dynamics': f'In the {country_name} market, clinical procurement committees prioritize device quality, warranty coverage, and local technical support capability.',
        'regulatory_watch': 'Local Ministry of Health medical device import license, CE/ISO 13485 certification, and Certificate of Origin are required.',
        'competitor_threat': 'Global IVF brands are seeking to defend market share through local distributors.',
        'commercial_guardrails': 'Cap device discount at 6%; do not authorize shipment without advance payment or Letter of Credit security.',
        'knowledge_profile': {
            'clinic_type': 'Mix of Private and Public Healthcare Centers.',
            'customs_code': 'Standard medical HS Code 9018.90 / 3822.00.',
            'cold_chain': 'Temperature-controlled (+2°C to +8°C) transfer for media solutions.',
            'payment_norms': 'Pre-shipment cash TT wire transfer or confirmed Letter of Credit.',
            'dos': 'Accelerate the decision cycle by providing trial samples to clinical embryologists.',
            'donts': 'Do not assume open-account or deferred-payment credit risk on the company.'
        }
    }

def generate_dual_consensus_decision(ai_rec, expert, partner_data):
    ai_disc = float(ai_rec['rec_device_discount'])
    expert_max = float(expert['expert_max_discount'])
    diff = ai_disc - expert_max
    
    if abs(diff) <= 1.0:
        consensus_status = "✅ TAM MUTABAKAT (AI & Uzman Uyumlu)"
        badge_color = "#10B981"
        final_discount = round((ai_disc + expert_max) / 2.0, 1)
        rationale = f"AI analytics ({ai_disc:.1f}%) and Expert field judgment ({expert_max:.1f}%) are in full consensus. Low-risk approval balanced with market purchasing power and company profitability targets."
        conditions = 'Standard contractual commitments, a 30-day order advance, and routine logistics planning are sufficient.'
    elif diff > 1.0:
        consensus_status = '⚠️ CONDITIONAL APPROVAL (Approved with Expert Safeguard Terms)'
        badge_color = "#FFB800"
        final_discount = round(expert_max + 0.5, 1)
        rationale = f"The AI model recommended {ai_disc:.1f}% for market expansion, while the Expert capped the ceiling at {expert_max:.1f}% due to field risks and list-price discipline. Expert-weighted consensus reached."
        conditions = f"Mandatory Safeguard Clause: {expert['commercial_guardrails']} Additionally, an annual minimum consumable pull-through clause must be included in the contract."
    else:
        consensus_status = '🛡️ STRATEGIC EXCEPTION (Market Penetration Priority)'
        badge_color = "#7DA8DF"
        final_discount = round(expert_max, 1)
        rationale = f"The Expert recommended strategic flexibility ({expert_max:.1f}%) to counter competitor pressure and lock in flagship clinics."
        conditions = f"Binding Condition: {expert['commercial_guardrails']}"
        
    final_sarf_disc = round(max(ai_rec['rec_consumable_discount'], expert['expert_rec_sarf_disc']), 1)
    
    return {
        'consensus_status': consensus_status,
        'badge_color': badge_color,
        'final_device_discount': final_discount,
        'final_sarf_discount': final_sarf_disc,
        'ai_discount': ai_disc,
        'expert_max_discount': expert_max,
        'rationale': rationale,
        'conditions': conditions,
        'final_bundle': f"{ai_rec['bundle_desc']} | 👨‍⚕️ Expert Stance: {expert['expert_stance']}",
        'rec_freight': ai_rec['rec_freight']
    }

def hash_code(s):
    h = 2166136261
    for ch in s:
        h = ((h ^ ord(ch)) * 16777619) & 0xFFFFFFFF
    return h

def rnd_val(s, k):
    x = (hash_code(s) + (k + 1) * 2654435761) & 0xFFFFFFFF
    x = ((x ^ (x >> 15)) * 2246822519) & 0xFFFFFFFF
    x = ((x ^ (x >> 13)) * 3266489917) & 0xFFFFFFFF
    return ((x ^ (x >> 16)) & 0xFFFFFFFF) / 4294967296.0

