            time_val = row.get("Time", row.get("Zaman", f"Scene {s_idx+1}"))
            vo_val = ""
            for k in row:
                if "seslendirme" in k.lower() or "voiceover" in k.lower() or "vo" in k.lower():
                    vo_val = row[k]
                    break
            visual_val = ""
            for k in row:
                if 'visual' in k.lower() or "kadraj" in k.lower() or "mikroskop" in k.lower():
                    visual_val = row[k]
