def normalize_country_str(s):
    if not s: return ""
    return str(s).lower().replace("i̇", "i").replace('ı', "i").replace('ü', "u").replace('ö', "o").replace('ş', "s").replace('ğ', "g").replace('ç', "c")

def detect_country_lang(country_name):
    c_lower = normalize_country_str(country_name)
    if any(k in c_lower for k in ["italy", "italia"]):
        return "it"
    elif any(k in c_lower for k in ["spain", "ispan"]):
        return "es"
    elif any(k in c_lower for k in ["german", "alman", "deutsch", "austri", "avustur", "switz", "isvic"]):
        return "de"
    elif any(k in c_lower for k in ["franc", "frans", "belg", "belc"]):
        return "fr"
    elif any(k in c_lower for k in ["egypt", "misir", "uae", "bae", "saudi", "suudi", "dubai", "gulf", "korfez", "qatar", "katar"]):
        return "ar"
    elif any(k in c_lower for k in ["turk", "azer"]):
        return "tr"
    else:
        return "en"

def format_outreach_salutation(p, lang_code, strat_mode):
    raw_person = p.get('contact_person', p.get('decision_maker', ''))
    is_generic_title = any(k in raw_person.lower() for k in ['director', 'responsible', 'manager', 'president', 'team', "yetkili", "kurul", "director", "lead", "officer", "board"])
    has_real_name = (not is_generic_title) and len(raw_person.strip()) > 3 and any(raw_person.startswith(prefix) for prefix in ["Dr", "Prof", "Mr", "Ms", "Dott", "Dra"])

    if lang_code == "it":
        if has_real_name: return f"Gentile {raw_person},"
        if strat_mode == "clinical": return "Gentile Responsabile del Laboratorio PMA / Direzione Scientifica,"
        elif strat_mode == "commercial": return "Gentile Amministratore Delegato / Direzione Generale e Acquisti,"
        else: return "Gentile Direzione Approvvigionamenti e Distribuzione Medica,"

    elif lang_code == "es":
        if has_real_name: return f"Estimado/a {raw_person},"
        if strat_mode == "clinical": return "Estimado/a Director/a de Laboratorio de Reproducción Asistida / Embriólogo Principal,"
        elif strat_mode == "commercial": return "Estimada Dirección General y Comité de Compras Médicas,"
        else: return "Estimada Dirección de Aprovisionamiento y Distribución Médica,"

    elif lang_code == "de":
        if has_real_name: return f"Sehr geehrte(r) Frau/Herr {raw_person},"
        if strat_mode == "clinical": return "Sehr geehrte(r) Frau/Herr IVF-Laborleitung / Leitende Reproduktionsbiologie,"
        elif strat_mode == "commercial": return 'Sehr geehrte Damen und Herren der Geschäftsführung & Finanzen,'
        else: return 'Sehr geehrte Damen und Herren der Geschäftsführung & Medizindistribution,'

    elif lang_code == "fr":
        if has_real_name: return f"Cher/Chère {raw_person},"
        if strat_mode == "clinical": return "Chère Confrère, Cher Confrère, Responsable du Laboratoire d'AMP,"
        elif strat_mode == "commercial": return "À l'attention de la Direction Générale et des Achats Médicaux,"
        else: return "À l'attention de la Direction Commerciale et de la Distribution Médicale,"

    elif lang_code == "ar":
        if strat_mode == "clinical": return "سعادة الأستاذ الدكتور / رئيس مختبر أطفال الأنابيب واستشاري علاج العقم المحترم،"
        elif strat_mode == "commercial": return "سعادة المدير العام / لجنة المشتريات الطبية الموقرة،"
        else: return "السادة / إدارة التوزيع والتجهيزات الطبية المحترمين،"

    elif lang_code == "tr":
        return f"Dear {raw_person if raw_person else 'Yetkili'},"

    else: # en
        if has_real_name: return f"Dear {raw_person},"
        if strat_mode == "clinical": return "Dear Head of IVF Laboratory / Senior Clinical Embryologist,"
        elif strat_mode == "commercial": return "Dear Chief Executive Officer / Executive Procurement Board,"
        else: return "Dear Director of Medical Procurement & Global Distribution,"


def format_executive_directive_block(custom_note, eff_lang, strat_mode="clinical"):
    if not custom_note or not custom_note.strip():
        return ""

    cn = custom_note.strip()
    cn_lower = cn.lower()

    has_eshre_guideline = any(w in cn_lower for w in ["eshre guid", "guideline", "guidelines", "rehber", 'guideline', "raccomandazioni", "guía", "leitlinie", "recommandation", "aoa guid"])
    has_whitepaper = any(w in cn_lower for w in ["whitepaper", "white paper", "scientific brief", "brief", 'clinical whitepaper', 'scientific dossier', 'case dossier', "clinical brief", "dossier", "white-paper"])
    has_discount = any(w in cn_lower for w in ["indirim", "iskonto", "discount", "sconto", "descuento", "rabatt", "remise", 'fleet', "fleet", "%", "quote", 'price'])
    has_congress = any(w in cn_lower for w in ["eshre kongre", "stand", "booth", "vip", "davet", "invitation", "congress", "kongresi"])
    has_dinner = any(w in cn_lower for w in ["yemek", 'dinner', "dinner", "cena", "dîner", "cena di lavoro", "comida", "عشاء", "ضيافة", "ziyafet", "hospitality", 'hospitality', "restoran", "restaurant", 'lunch', "kahve", "coffee"])

    # ENGLISH
    if eff_lang == "en":
        sections = [f"• Executive Directive & Custom Terms (Executive Special Directive):\n\"{cn}\""]
        if has_eshre_guideline:
            sections.append(
                "• ESHRE Guideline Compliance for Assisted Oocyte Activation (AOA):\n"
                "In strict accordance with ESHRE Good Practice Recommendations on Assisted Oocyte Activation (AOA), the ZEUS Pulse Stimulator (ZPS 26) delivers a controlled, physiological micro-pulse electrical activation protocol. This eliminates operator variability and overcomes the severe epigenetic cytotoxicity and chemical cellular stress associated with chemical calcium ionophores (A23187 / calcimycin). ESHRE literature confirms that electrical activation establishes a safe, physiological intracellular calcium transient, delivering exceptional safety in recurrent fertilization failure (TFF) cohorts."
            )
        if has_whitepaper:
            sections.append(
                "• Enclosed Clinical Whitepaper (Executive Scientific Brief):\n"
                "Enclosed with this proposal, please find our comprehensive 1-page Executive Clinical Whitepaper & Case Brief summarizing multicentric peer-reviewed evidence:\n"
                "  - 2PN Fertilization Rate: increased from 24.6% to 82.3% (+57.7% clinical recovery, p < 0.001)\n"
                "  - Day-5 Usable Blastocyst Utilization: boosted by 2.2-fold (from 21.4% to 48.1%)\n"
                "  - Oocyte Integrity & Zero Lysis: membrane degeneration held <0.8%\n"
                "  - Certified Quality Assurance: CE Certified (Class IIa Medical Device), Mouse Embryo Assay (MEA >80%), and Endotoxin LAL (<0.05 EU/ml) certified."
            )
        if has_discount:
            sections.append(
                "• Tailored Institutional Fleet Economics:\n"
                "Per executive directive, we offer an institutional 10% fleet discount on multi-unit acquisitions, alongside preferential per-cycle pricing under annual Z-Dish consumable agreements."
            )
        if has_congress and not has_eshre_guideline:
            sections.append(
                "• ESHRE Congress VIP Stand Invitation:\n"
                "We cordially invite your senior embryology and executive delegation to visit the ZEUS Bioscience booth at the upcoming ESHRE Congress for an exclusive protocol workshop."
            )
        if has_dinner:
            sections.append(
                "• VIP Business Dinner & Executive Hospitality Invitation:\n"
                "On the occasion of the upcoming congress or our scheduled executive delegation visit, we would be deeply honored to host your esteemed clinical leadership for a private VIP dinner and scientific discussion to review protocol integration and strategic partnership opportunities in a cordial setting."
            )

        return '\n\n------------------------------------------------------------\n📌 EXECUTIVE DIRECTIVE & TAILORED PROPOSAL CLAUSE (EXECUTIVE SPECIAL DIRECTIVE):\n------------------------------------------------------------\n' + "\n\n".join(sections) + "\n------------------------------------------------------------\n"

    # TURKISH
    elif eff_lang == "tr":
        sections = [f"• Executive Directive & Tailored Proposal Clause:\n\"{cn}\""]
        if has_eshre_guideline:
            sections.append(
                '• ESHRE Guideline Compliance (Electrical Oocyte Activation - AOA):\nFully aligned with the ESHRE Good Practice Recommendations, ZEUS Pulse Stimulator (ZPS 26) delivers a physiological micro-pulse electrical protocol that eliminates the cytotoxic risks of chemical calcium ionophores (A23187) on embryo epigenetics. It achieves 79.37% Grade I & II high-quality embryo development in TFF and globozoospermia cases.'
            )
        if has_whitepaper:
            sections.append(
                '• Attached Clinical Whitepaper (Executive Scientific Brief):\nThe 1-page Clinical Whitepaper (Executive Scientific Brief) attached to our message presents complete peer-reviewed multicenter study data (2PN fertilization rate increasing from 24.6% to 82.3%, a 2.2x increase in Day-5 usable blastocyst yield, MEA >80%, and CE Class IIa certification documentation).'
            )
        if has_discount:
            sections.append(
                '• Special Fleet Discount & Consumables Pricing Advantage:\nWith the approval of our Executive Board, we are pleased to offer your institution a 10% corporate fleet discount on orders of 3+ devices and preferential per-case unit pricing with an annual commitment of 200 boxes of Z-Dish consumables.'
            )
        if has_congress and not has_eshre_guideline:
            sections.append(
                '• VIP Booth Invitation at ESHRE Congress:\nWe would be honored to host your senior embryology delegation as VIP guests at the ZEUS Bioscience booth during the 2027 ESHRE Congress.'
            )
        if has_dinner:
            sections.append(
                "• VIP Business Dinner & Scientific Consultation Invitation:\nDuring the upcoming congress or our team's scheduled visit to your institution, we would be deeply honored to host your clinical delegation and esteemed director for a private VIP Business Dinner & Strategic Discussion to exchange clinical insights and explore collaboration."
            )

        return '\n\n------------------------------------------------------------\n📌 EXECUTIVE DIRECTIVE & TAILORED PROPOSAL CLAUSE:\n------------------------------------------------------------\n' + "\n\n".join(sections) + "\n------------------------------------------------------------\n"

    # ITALIAN
    elif eff_lang == "it":
        sections = [f"• Disposizioni Strategiche & Nota Direzionale (Executive Directive):\n\"{cn}\""]
        if has_eshre_guideline:
            sections.append(
                "• Conformità alle Linee Guida ESHRE per l'Attivazione Oocitaria Assistita (AOA):\n"
                "In piena aderenza alle raccomandazioni di buona pratica clinica ESHRE sull'Attivazione Oocitaria Assistita (AOA), il sistema ZEUS Pulse Stimulator offre un protocollo di attivazione elettrica a micro-impulsi controllati. Questo approccio supera la tossicità epigenetica e lo stress cellulare degli ionofori chimici di calcio (A23187), garantendo un'attivazione fisiologica sicura nei fallimenti ripetuti di fecondazione (TFF)."
            )
        if has_whitepaper:
            sections.append(
                "• Whitepaper Clinico Allegato (Executive Scientific Brief):\n"
                "Troverete in allegato il nostro Whitepaper Clinico Esecutivo contenente i dati multicentrici pubblicati: tasso di fertilizzazione 2PN dall'82.3% (rispetto al 24.6% basale), resa di blastocisti a Giorno 5 incrementata di 2.2 volte, marcatura CE Classe IIa e test MEA >80%."
            )
        if has_discount:
            sections.append(
                "• Condizioni Commerciali per Flotta Istituzionale:\n"
                "Come concordato dalla direzione, confermiamo uno sconto del 10% sulla flotta hardware e tariffe consumabili Z-Dish bloccate su base pluriennale."
            )
        if has_dinner:
            sections.append(
                "• Invito Esclusivo a Cena di Lavoro & Confronto Scientifico VIP:\n"
                "In occasione del prossimo congresso o della nostra visita istituzionale, avremmo il vero piacere e l'onore di invitare la Vostra stimata direzione clinica a una cena di lavoro per approfondire in un contesto informale e collegiale i protocolli clinici e le sinergie di partnership."
            )

        return "\n\n------------------------------------------------------------\n📌 DISPOSIZIONI STRATEGICHE: DIRETTIVA ESECUTIVA & NOTE PERSONALIZZATE:\n------------------------------------------------------------\n" + "\n\n".join(sections) + "\n------------------------------------------------------------\n"

    # SPANISH
    elif eff_lang == "es":
        sections = [f"• Directiva Ejecutiva y Cláusula Personalizada (Executive Directive):\n\"{cn}\""]
        if has_eshre_guideline:
            sections.append(
                "• Cumplimiento de las Guías Clínicas ESHRE (AOA Eléctrico):\n"
                "En estricto cumplimiento con las recomendaciones de buena práctica de ESHRE sobre Activación Oocitaria Asistida (AOA), el ZEUS Pulse Stimulator implementa una estimulación micropulsada eléctrica fisiológica, eliminando por completo los riesgos de citotoxicidad epigenética de los ionóforos químicos (A23187)."
            )
        if has_whitepaper:
            sections.append(
                "• Whitepaper Clínico Adjunto (Executive Scientific Brief):\n"
                "Adjuntamos nuestro Whitepaper Clínico Ejecutivo con evidencia multicéntrica publicada: tasa de fecundación 2PN del 82.3% en cohortes TFF, multiplicación de blastocistos Día-5 por 2.2x y certificación CE Clase IIa con MEA >80%."
            )
        if has_discount:
            sections.append(
                "• Condiciones Especiales de Flota Institucional:\n"
                "Confirmamos un 10% de descuento en la adquisición de flota de equipos y tarifas preferenciales en consumibles Z-Dish por volumen anual."
            )
        if has_dinner:
            sections.append(
                "• Invitación a Cena de Trabajo & Encuentro Científico VIP:\n"
                "Con motivo del próximo congreso o de nuestra próxima visita, sería un auténtico honor invitar a su prestigiosa dirección médica a una cena de trabajo exclusiva para compartir visiones clínicas y evaluar sinergias institucionales."
            )

        return "\n\n------------------------------------------------------------\n📌 DIRECTIVA EJECUTIVA: CLÁUSULA PERSONALIZADA & CONDICIONES ESPECIALES:\n------------------------------------------------------------\n" + "\n\n".join(sections) + "\n------------------------------------------------------------\n"

    # GERMAN
    elif eff_lang == "de":
        sections = [f"• Strategische Direktionsvorgabe & Sonderklausel (Executive Directive):\n\"{cn}\""]
        if has_eshre_guideline:
            sections.append(
                '• Einhaltung der ESHRE-Leitlinien für Assistierte Oozyten-Aktivierung (AOA):\nIn voller Übereinstimmung mit den ESHRE Good Practice Recommendations für AOA bietet der ZEUS Pulse Stimulator eine kontrollierte elektrische Mikropuls-Aktivierung, die chemische Ionophor-Toxizität (A23187) vollständig eliminiert.'
            )
        if has_whitepaper:
            sections.append(
                '• Beigefügtes Klinisches Whitepaper (Executive Scientific Brief):\nIm Anhang finden Sie unser 1-seitiges Executive Whitepaper mit publizierten multizentrischen Daten: Steigerung der 2PN-Befruchtung auf 82,3% bei TFF, 2,2-facher Zuwachs an Tag-5-Blastozysten und CE-Zertifizierung mit MEA >80%.'
            )
        if has_dinner:
            sections.append(
                '• Einladung zum Arbeitsessen & Wissenschaftlichen Dialog:\nIm Rahmen des kommenden Fachkongresses oder unseres Besuchs laden wir Ihre ärztliche Leitung herzlich zu einem Arbeitsessen ein, um die klinischen Daten und Implementierungsmodalitäten im persönlichen Rahmen zu besprechen.'
            )

        return "\n\n------------------------------------------------------------\n📌 STRATEGISCHE VORGABE: DIREKTIONSANWEISUNG & SONDERKONDITIONEN:\n------------------------------------------------------------\n" + "\n\n".join(sections) + "\n------------------------------------------------------------\n"

    # FRENCH
    elif eff_lang == "fr":
        sections = [f"• Directive Exécutive & Termes Personnalisés (Executive Directive):\n\"{cn}\""]
        if has_eshre_guideline:
            sections.append(
                "• Conformité aux recommandations ESHRE pour l'Activation Ovocytaire Assistée (AOA):\n"
                "Conformément aux recommandations de bonnes pratiques de l'ESHRE, le ZEUS Pulse Stimulator applique un protocole d'activation électrique non toxique sans ionophores chimiques (A23187)."
            )
        if has_whitepaper:
            sections.append(
                "• Whitepaper Clinique Joint (Executive Scientific Brief):\n"
                "Veuillez trouver ci-joint notre Whitepaper Clinique Exécutif résumant nos résultats multicentriques: fertilisation 2PN atteignant 82.3% en échec de fécondation, blastocystes J5 multipliés par 2.2 et marquage CE Classe IIa."
            )
        if has_dinner:
            sections.append(
                "• Invitation à un Dîner de Travail & Échange Scientifique VIP:\n"
                "À l'occasion du prochain congrès ou de notre visite, nous serions très honorés de convier votre direction médicale à un dîner de travail afin d'échanger sur les perspectives cliniques et de partenariat."
            )

        return "\n\n------------------------------------------------------------\n📌 DIRECTIVE EXÉCUTIVE: TERMES PERSONNALISÉS & DISPOSITIONS SPÉCIALES:\n------------------------------------------------------------\n" + "\n\n".join(sections) + "\n------------------------------------------------------------\n"

    # ARABIC
    elif eff_lang == "ar":
        sections = [f"• التوجيه التنفيذي الخاص والشروط المحددة (Executive Directive):\n\"{cn}\""]
        if has_eshre_guideline:
            sections.append(
                "• التوافق التام مع إرشادات الجمعية الأوروبية للخصوبة (ESHRE) للتنشيط الكهربائي (AOA):\n"
                "مطابقة تامة لتوصيات ESHRE في تنشيط البويضات كهربائياً بتقنية النبضات الدقيقة الفسيولوجية دون مخاطر سمية الكالسيوم الكيميائية (A23187)."
            )
        if has_whitepaper:
            sections.append(
                "• الملف الإكلينيكي المرفق (Clinical Whitepaper - Executive Brief):\n"
                "نرفق لسيادتكم الملف العلمي التنفيذي الموثق: رفع نسب التخصيب 2PN إلى 82.3%، وزيادة أجنة اليوم الخامس 2.2 ضعف، بشهادة CE الأوروبية وفحص MEA >80%."
            )
        if has_dinner:
            sections.append(
                "• دعوة عشاء عمل واستضافة علمية رفيعة المستوى (VIP Business Dinner Invitation):\n"
                "يسعدنا ويشرفنا توجيه دعوة خاصة لسيادتكم ولفريقكم الطبي الموقر لحضور عشاء عمل علمي على هامش المؤتمر القادم أو خلال زيارتنا الميدانية، لمناقشة البروتوكولات الإكلينيكية وتعزيز أواصر الشراكة الاستراتيجية."
            )

        return "\n\n------------------------------------------------------------\n📌 التوجيه التنفيذي الخاص والشروط المعتمدة:\n------------------------------------------------------------\n" + "\n\n".join(sections) + "\n------------------------------------------------------------\n"

    return ""


