def get_country_device_suitability(c_row):
    """
    Computes fit score (0-100), priority tier, and rationale for each of the 4 ZEUS technologies
    based on national IVF statistics, clinical demographics, and official 2026 catalog intelligence.
    """
    clinics = int(c_row.get('clinics', 40)) if c_row is not None and 'clinics' in c_row else 40
    cycles = int(c_row.get('cycles', 20000)) if c_row is not None and 'cycles' in c_row else 20000
    gdp_pc = int(c_row.get('gdp_pc', 25000)) if c_row is not None and 'gdp_pc' in c_row else 25000
    icsi_pct = float(c_row.get('icsi_pct', 80.0)) if c_row is not None and 'icsi_pct' in c_row else 80.0
    c_name = str(c_row.get('name', 'Global')) if c_row is not None else 'Global'
    c_code = str(c_row.get('code', 'INT')) if c_row is not None else 'INT'
    
    cycles_per_clinic = cycles / max(1, clinics)

    # Check 2026 network presence
    dist_match = next((d for d in ZEUS_GLOBAL_REFERENCE_NETWORK_2026['distributors'] if c_name in d['countries']), None)
    ref_match = [r for r in ZEUS_GLOBAL_REFERENCE_NETWORK_2026['international_centers'] if r['country'] == c_name]
    
    # 1. ZPS 26 (ZEUS Pulse Stimulator (ZPS 26))
    has_zps_ref = c_code in ['IQ', 'JO', 'TR', 'KR', 'JP', 'DE', 'KW', 'QA', 'SA', 'EG', 'SY', 'AZ']
    zps_boost = 15 if dist_match and 'ZEUS Pulse Stimulator' in str(dist_match.get('focus_products', [])) else (10 if has_zps_ref else 0)
    zps_score = min(99, int(60 + (icsi_pct - 60) * 0.7 + (10 if gdp_pc > 15000 else 0) + zps_boost))
    zps_tier = 'Tier 1: Priority Standard' if zps_score >= 85 else ('Tier 2: Complementary' if zps_score >= 75 else 'Tier 3: Niche')
    
    if dist_match and c_name == 'Kuwait':
        zps_rationale = 'In the Kuwait market, our official distributor ATC Kuwait installed 3 Pulse Stimulators in 2025. Consumable pull-through (Electro Dish) and new unit sales across public and private IVF centers are top priorities.'
    elif dist_match and c_name in ['Jordan', 'Iraq']:
        zps_rationale = 'With Sirius Pharm Company and Farah/Sadeen/Amal references, recurring Electro Dish (ZPS13-002) and Electroliquid consumable pull-through is secured across the installed base of 18 Pulse Stimulator units.'
    elif dist_match and c_name == 'South Korea':
        zps_rationale = 'With SJNU INC and Suji/Dongtan Maria Hospital references, Electrical AOA and the Tanaka ROSI protocol serve as the market standard; it is our highest-penetration ESHRE add-on-aligned market.'
    else:
        zps_rationale = f"In the {c_name} market, with {icsi_pct:.0f}% ICSI adoption and challenging cases (advanced maternal age, TFF), it delivers direct fertilization improvement backed by Baltacı et al. (62% fertilization) and Tanaka ROSI clinical evidence."

    # 2. Black-Box BioPSafe ZBB25-001
    pgt_friendly = c_code in ['ES', 'US', 'AE', 'TR', 'IT', 'GR', 'QA', 'SA', 'UK', 'CY', 'JO']
    bb_boost = 15 if (ref_match or (dist_match and 'Black-Box' in str(dist_match.get('focus_products', [])))) else (10 if pgt_friendly else 0)
    biopsafe_score = min(99, int(55 + (15 if pgt_friendly else 0) + (15 if gdp_pc > 25000 else 5) + (10 if cycles_per_clinic > 400 else 0) + bb_boost))
    biopsafe_tier = 'Tier 1: High Priority (PGT Leader)' if biopsafe_score >= 85 else ('Tier 2: Emerging Segment' if biopsafe_score >= 70 else 'Tier 3: Selected Centers')
    
    if c_name in ['United Arab Emirates', 'Saudi Arabia']:
        biopsafe_rationale = f"In the {c_name} market, at A+ reference centers such as Fakih IVF Dubai and King Fahad Medical City, the 13-IR-sensor Black-Box platform (ZBB25-001) and dual-tablet HD audit trail are the strongest purchasing drivers."
    else:
        biopsafe_rationale = f"In {c_name} clinics, during PGT-A/PGT-M embryo biopsy, 13 IR sensors, dual tablets, and foot pedals eliminate lane-skipping and PCR tube mismatch risks; its Multi-Purpose module also secures routine ICSI."

    # 3. Mismatch Blocker (ZMB-7T)
    mb_boost = 15 if (dist_match and 'Mismatch Blocker' in str(dist_match.get('focus_products', []))) else (10 if clinics > 40 else 0)
    mb_score = min(99, int(50 + (20 if cycles > 20000 or clinics > 30 else 5) + (15 if gdp_pc > 20000 else 5) + (10 if cycles_per_clinic > 350 else 0) + mb_boost))
    mb_tier = 'Tier 1: Corporate Standard' if mb_score >= 85 else ('Tier 2: Mid-to-Large Scale' if mb_score >= 72 else "Tier 3: Pilot Merkezler")
    mb_rationale = f"Performs 7-stage electronic witnessing for sperm, oocyte, and embryo samples across {clinics} active clinics in the {c_name} market. Compared to expensive RFID chips, it delivers 75% OPEX savings via unlimited free barcodes and a per-cycle coin model."

    # 4. Smart Cryo-Tools (ZCT25 - 4X Tank Optimization)
    cryo_boost = 15 if dist_match else (10 if clinics > 25 else 0)
    cryo_score = min(99, int(65 + (15 if cycles > 10000 else 5) + (10 if clinics > 20 else 5) + (10 if cycles_per_clinic > 300 else 0) + cryo_boost))
    cryo_tier = 'Tier 1: Universal Need (4X Capacity)' if cryo_score >= 85 else ('Tier 2: High Savings' if cryo_score >= 75 else 'Tier 3: Standard')
    cryo_rationale = f"Increases the existing liquid nitrogen tank capacity of {c_name} clinics by a net 4X (40 straws per cane). Prevents $35,000–$50,000 in new tank investment per clinic and ensures >95% post-thaw survival by preventing thermal shock with liquid-nitrogen-reservoir octagonal goblets."

    return {
        'zps26': {'score': zps_score, 'tier': zps_tier, 'rationale': zps_rationale},
        'biopsafe': {'score': biopsafe_score, 'tier': biopsafe_tier, 'rationale': biopsafe_rationale},
        'mismatch_blocker': {'score': mb_score, 'tier': mb_tier, 'rationale': mb_rationale},
        'smart_cryo': {'score': cryo_score, 'tier': cryo_tier, 'rationale': cryo_rationale}
    }



