def evaluate_decision_note(note):
    '\n    Evaluates a competitor decision note against Decision Center corporate governance:\n    - 4-Pool Dish ROI ($100 Dist / $150 Clinic; Single patient: $150, 4-patient shared: $37.50/case)\n    - Zero Free Demo Rule (Only 100+ boxes consumable commitment or paid workshop)\n    - Electrical AOA Clinical Protocol (sub-1.2% lysis, CE Class IIa, zero EMF)\n    - Hard currency / price protection ($ USD pegged)\n    '
    memo = (note.get('decision_note', '') + " " + note.get('selected_strategy', '') + " " + " ".join(note.get('contract_clauses', []))).lower()
    
    score = 75
    findings = []
    
    # 1. Consumable & 4-Pool ROI Check
    if any(k in memo for k in ['4 pool', '4-pool', 'z-dish', 'consumable commitment', '100+ kutu', '60 kutu', '75 kutu', '100 kutu', 'cycle coin', 'cycle coin']):
        score += 15
        findings.append('✓ 4-Pool Z-Dish ($100 Dist / $150 Clinic; 4-patient shared $37.50/case zero mismatch) ROI and binding consumable commitment in place.')
    else:
        score -= 15
        findings.append('⚠️ No binding minimum consumable commitment clause detected; consumable pull-through risk present.')
        
    # 2. Free Demo Compliance
    if any(k in memo for k in ['no free demo', 'demo yok', 'paid case workshop', 'case workshop', 'conditional demo', 'paid workshop', 'starter package']):
        score += 10
        findings.append('✓ Free demo blocked (Only 100+ boxes conditional demo or paid workshop approved).')
    elif 'free demo' in memo or 'serbest demo' in memo:
        score -= 25
        findings.append('⛔ Free demo risk detected (Strictly Prohibited by Board Resolution).')
        
    # 3. Clinical & Legal Compliance
    if any(k in memo for k in ['baltacı', 'ebner', 'sub-%1.2', 'lizis', 'ce certified', 'class iia', 'zero emf', 'ir sensor']):
        score += 5
        findings.append('✓ Supported by peer-reviewed clinical publications and patented hardware superiority.')
        
    # 4. Financial & Currency Guarantee
    if any(k in memo for k in ['usd', 'dolar', 'price protection', 'kur riski', 'teminat', 'penalty clause']):
        score += 5
        findings.append('✓ Price protection ($ USD pegged) or bank guarantee collateral secured.')
        
    score = max(25, min(99, score))
    
    if score >= 85:
        risk = 'Low Risk (High Financial Return)'
        color = "#10B981"
        auto_verdict = 'Approved & Active'
    elif score >= 65:
        risk = 'Controlled Risk (Conditional Monitoring)'
        color = "#FFB800"
        auto_verdict = 'Conditional Approval / Under Review'
    else:
        risk = 'High Risk (Concession / Violation)'
        color = "#F43F5E"
        auto_verdict = 'Revision Required / Rejected'
        
    return {
        "score": score,
        "risk_level": risk,
        "badge_color": color,
        "auto_verdict": auto_verdict,
        "findings": findings
    }


