    with reg_tab5:
        st.markdown('#### ➕ Add New Ministry Ruling or Regulatory Note from the Field')
        with st.form(f"form_add_reg_{sel_reg_country}"):
            r_num = st.text_input('Decree / Ruling No.:', placeholder='e.g., MOH-2026/14')
            r_title = st.text_input('Subject / Title:', placeholder='e.g., New Embryo Biopsy Accreditation Decree')
