def render_active_omni_search_hub(query_str):
    """
    Live Omni-Search Engine with Smart Tab Auto-Prioritization & Direct Table Navigation.
    Automatically focuses on the tab that contains matching results, provides one-click
    category jump shortcuts, and item-level navigation buttons to take the user directly
    to the target dashboard view.
    """
    if not query_str or not query_str.strip():
        return

    q = query_str.strip().lower()
    q_clean = query_str.strip()

    # Match across entities
    matched_firms = []
    if 'GLOBAL_PROSPECT_RADAR' in globals():
        for c_k, p_list in GLOBAL_PROSPECT_RADAR.items():
            for f in p_list:
                f_txt = f"{f.get('name','')} {c_k} {f.get('country','')} {f.get('city','')} {f.get('category','')} {f.get('tier','')} {f.get('contact_person','')} {f.get('email','')} {f.get('phone','')} {f.get('strategy_rationale','')} {f.get('why_target','')} {f.get('product_match','')}".lower()
                if q in f_txt:
                    item_copy = dict(f)
                    item_copy['country'] = f.get('country') or c_k
                    item_copy['strategy_rationale'] = f.get('strategy_rationale') or f.get('why_target', '')
                    matched_firms.append(item_copy)

    if 'dists_with_rev' in globals():
        for d in dists_with_rev:
            d_txt = f"{d.get('name','')} {d.get('country_name','')} {d.get('city','')} {d.get('account_type','')} {d.get('primary_contact','')} {d.get('email','')}".lower()
            if q in d_txt:
                matched_firms.append({
                    'name': d.get('name'),
                    'country': d.get('country_name'),
                    'city': d.get('city', ''),
                    'category': d.get('account_type', 'Distributor'),
                    'tier': '⭐ Tier 1' if d.get('revenue', 0) > 20000 else 'Tier 2',
                    'contact_person': d.get('primary_contact', 'Yetkili'),
                    'email': d.get('email', 'info@distributor.com'),
                    'phone': d.get('phone', ''),
                    'web': d.get('website', ''),
                    'strategy_rationale': f"Total Revenue: ${d.get('revenue', 0):,.2f} | Installed Base: {d.get('devices_count', 0)} Devices | Status: {d.get('status', 'active')}"
                })

    matched_cultures = []
    _culture_source = globals().get('GLOBAL_COUNTRY_BUYING_BEHAVIOR') or globals().get('CULTURAL_NEGOTIATION_PLAYBOOK') or {}
    for c_name, b in _culture_source.items():
        b_txt = f"{c_name} {b.get('culture_title', '')} {b.get('decision_hierarchy', '')} {b.get('bargaining_advice', '')} {b.get('primary_proof_point', '')} {b.get('preferred_deal_model', '')} {b.get('dining_hospitality_protocol', '')} {b.get('dining_contract_rule', '')} {b.get('contract_closing_strategy', '')} {b.get('cultural_taboos', '')} {b.get('email_tone_guidance', '')}".lower()
        if q in b_txt:
            matched_cultures.append({"country": c_name, **b})

    matched_tenders = []
    _tender_source = globals().get('GLOBAL_TENDER_PROCUREMENT_INTEL') or globals().get('GLOBAL_TENDERS_INTEL_2026') or {}
    for c_name, t_data in _tender_source.items():
        t_txt = f"{c_name} {t_data.get('tender_authority','')} {t_data.get('official_authority','')} {t_data.get('typical_budget_range','')} {t_data.get('est_budget_range','')} {t_data.get('legal_framework','')} {str(t_data.get('procurement_portals',[]))}".lower()
        if q in t_txt:
            matched_tenders.append({"country": c_name, "intel": t_data})

    matched_products = []
    prod_items = [
        {"title": "ZEUS Pulse Stimulator (ZPS 26)", "badge": "Elektriksel Oosit Aktivasyon (AOA)", "specs": "Micro-pulse 0-40V, 1-99µs, 4 pools × 5 oocytes (20 max), CE Class IIa", "cert": 'CE Class IIa (Certified)', "price": "$14,000 - $16,000 USD", "indications": 'Total Fertilization Failure (TFF), Severe Male Factor (TESE/Globozoospermia)'},
        {"title": "ZEUS BioPSafe (ZBS26 Black-Box)", "badge": 'Embryo Biopsy Workstation', "specs": '13 IR optical sensors (Laser-Free - Zero Thermal Damage), HEPA H14 micro-cabinet, 30s trophectoderm biopsy, zero thermal DNA damage', "cert": "CE Class I", "price": "$12,000 - $14,000 USD", "indications": 'PGT-A / PGT-M Biopsy, Genetic Sample Tracking'},
        {"title": "ZEUS Mismatch Blocker (ZMB-7T)", "badge": '7-Terminal Electronic Witnessing', "specs": '7 independent RFID stations, Free of Charge Barcodes, $25 USD / Cycle license', "cert": "CE Class I", "price": "$12,000 - $13,000 USD", "indications": 'Sample Mix-Up Prevention, Medicolegal Malpractice Shield'},
        {"title": "ZEUS Smart Cryo-Tools (ZCT26)", "badge": "4X Kriyobank & Vitrifikasyon", "specs": 'Octagonal goblet geometry, 4X tank capacity increase, pinpoint straw addressing', "cert": "CE Class I", "price": "$6,000 - $7,000 USD", "indications": 'Oocyte & Embryo Vitrification, Liquid Nitrogen Tank Optimization'},
        {"title": "ZEUS Electro Dish (ZPS13-002)", "badge": 'Calcium-Free Activation Consumable', "specs": '4 pools × 5 oocytes = max 20 oocytes capacity, single-use gamma sterile', "cert": "CE Class IIa", "price": "$100 USD / Boxes", "indications": "Elektriksel AOA Vaka Rutini"},
        {"title": 'ZEUS Lyophilized Powder Activation Media', "badge": '1-Year Shelf-Life Media', "specs": 'Lyophilized powder formulation, 12-month ambient/cold stability, zero cold-chain spoilage risk', "cert": "CE Class IIa", "price": '$75 USD / Vial', "indications": 'Electrical Conductivity & Gamete Protection'}
    ]
    is_prod_search = any(w in q for w in ['device', 'product', 'consumables', 'price', "dish", "pulse", "biopsafe", "mismatch", "cryo", "zps", "zmb", "zbs", "zct", "lazer", "piezo"])
    for pr in prod_items:
        pr_txt = f"{pr['title']} {pr['badge']} {pr['specs']} {pr['cert']} {pr['indications']}".lower()
        if q in pr_txt or is_prod_search:
            matched_products.append(pr)

    tot_matches = len(matched_firms) + len(matched_cultures) + len(matched_tenders) + len(matched_products)

    # Render Header Card with Clear Button
    st.markdown(f"""
    <div style="background:linear-gradient(135deg, rgba(15,23,42,0.96) 0%, rgba(30,41,59,0.94) 100%);border:1.5px solid #7DA8DF;border-radius:12px;padding:14px 18px;margin-bottom:14px;box-shadow:0 6px 20px rgba(125,168,223,0.2);">
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">
            <div style="display:flex;align-items:center;gap:10px;">
                <span style="font-size:20px;">🔍</span>
                <div>
                    <h4 style="margin:0;color:#FFFFFF;font-size:16px;font-weight:800;">
                        Live Search Results: <span style="color:#7DA8DF;">"{q_clean}"</span>
                    </h4>
                    <div style="color:#94A3B8;font-size:12px;margin-top:2px;">
                        Total <b style="color:#10B981;">{tot_matches}</b> results matched ({len(matched_cultures)} Culture & Contracts, {len(matched_firms)} Organizations/Companies, {len(matched_tenders)} Tenders, {len(matched_products)} Products/Regulations)
                    </div>
                </div>
            </div>
        </div>
    </div>
    """, unsafe_allow_html=True)

    c_btn1, c_btn2 = st.columns([1.2, 4.0])
    with c_btn1:
        if st.button('Clear Search (Return to Default)', key="btn_clear_omni_search_active", use_container_width=True):
            st.session_state["omni_search_input"] = ""
            st.rerun()

    if tot_matches == 0:
        st.warning(f"No results found matching '{q_clean}'. Please try again with a company name, country (e.g., Saudi, Italy, Egypt), device (ZPS 26, BioPSafe), or keyword (dining, tender, contract).")
        return

    # QUICK JUMP SHORTCUT BUTTONS (Doğrudan İlgili Masaya / Sekmeye Git)
    st.markdown('\n    <div style="background:rgba(255,255,255,0.02);border:1px dashed rgba(125,168,223,0.25);border-radius:8px;padding:8px 12px;margin-bottom:12px;">\n        <span style="font-size:11.5px;color:#CBD5E1;font-weight:700;">🚀 Go Directly to Relevant Desk / Tab (One-Click Jump):</span>\n    </div>\n    ', unsafe_allow_html=True)

    jump_cols = st.columns(4)
    with jump_cols[0]:
        if len(matched_cultures) > 0:
            first_c = matched_cultures[0]['country']
            if st.button(f"Culture & Contracts ({len(matched_cultures)}) ", key="btn_jump_cult_hdr", use_container_width=True, type="primary"):
                st.session_state["main_nav_radio"] = '01 / Market Intelligence & Country Analysis'
                st.session_state["c360_single_country_select"] = first_c
                st.session_state["omni_search_input"] = ""
                st.rerun()
    with jump_cols[1]:
        if len(matched_firms) > 0:
            if st.button(f"Firmalar & CRM ({len(matched_firms)}) ", key="btn_jump_firm_hdr", use_container_width=True):
                st.session_state["main_nav_radio"] = '04 / B2B & Medical Outreach Network'
                st.session_state["omni_search_input"] = ""
                st.rerun()
    with jump_cols[2]:
        if len(matched_tenders) > 0:
            if st.button(f"Public Tenders ({len(matched_tenders)}) ", key="btn_jump_tend_hdr", use_container_width=True):
                st.session_state["main_nav_radio"] = '01 / Market Intelligence & Country Analysis'
                st.session_state["omni_search_input"] = ""
                st.rerun()
    with jump_cols[3]:
        if len(matched_products) > 0:
            if st.button(f"Devices & Regulations ({len(matched_products)}) ", key="btn_jump_prod_hdr", use_container_width=True):
                st.session_state["main_nav_radio"] = '01 / Market Intelligence & Country Analysis'
                st.session_state["omni_search_input"] = ""
                st.rerun()

    # SMART TAB AUTO-PRIORITIZATION: Categories with results appear FIRST!
    cat_defs = [
        {"id": "cultures", "title": f"🌍 Cultural Sales & Contract Strategy ({len(matched_cultures)})", "count": len(matched_cultures)},
        {"id": "firms", "title": f"🏢 Firmalar & Klinikler ({len(matched_firms)})", "count": len(matched_firms)},
        {"id": "tenders", "title": f"🏛️ Tenders & Specifications ({len(matched_tenders)})", "count": len(matched_tenders)},
        {"id": "products", "title": f"⚡ Devices, Products & Regulations ({len(matched_products)})", "count": len(matched_products)},
    ]
    # Sort descending by match count so non-empty categories are focused first!
    sorted_cats = sorted(cat_defs, key=lambda x: x["count"], reverse=True)

    tab_objects = st.tabs([c["title"] for c in sorted_cats])

    for tab_obj, c_meta in zip(tab_objects, sorted_cats):
        with tab_obj:
            if c_meta["id"] == "cultures":
                if not matched_cultures:
                    st.info('No cultural sales or contract rules matched this search.')
