        neon_colors = ['#7DA8DF', '#10B981', '#8B5CF6', '#F59E0B', '#EC4899', '#7DA8DF']

        if chart_3d_mode == "3D Holografik Sahne (360°)":
            # Dynamic Three.js items construction with Floating 3D Product & Percentage Badges
            import math
